screenPanels.initJs:
function(container, apiUrl, tables) {
  let editingId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="cursor: pointer;">
        <td>${new Date(r.生産開始日時).toLocaleString('ja-JP', {year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit'})}</td>
        <td>${r.生産ライン名 || '-'}</td>
        <td>${r.製品名 || '-'}</td>
        <td style="text-align: right;">${r.生産数量?.toLocaleString() || 0}</td>
        <td style="text-align: right;">${r.良品数量?.toLocaleString() || 0}</td>
        <td style="text-align: right;">${r.不良品数量?.toLocaleString() || 0}</td>
        <td>${r.作業者名 || '-'}</td>
        <td style="text-align: right;">${r.稼働率 || 0}%</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="font-size: 12px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 12px; padding: 4px 8px; margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ描画
  renderRows(tables[4]?.records || []);

  // 計画比較の更新
  function updatePlanComparison(productId, actualQuantity) {
    const planTable = tables[3]; // 生産計画テーブル
    const productTable = tables[2]; // 製品テーブル

    if (!productId) {
      container.querySelector('#plan-comparison').style.display = 'none';
      container.querySelector('#no-plan-message').style.display = 'block';
      return;
    }

    const plan = planTable?.records?.find(p => p.製品ID === productId);
    const product = productTable?.records?.find(p => p.製品ID === productId);

    if (plan && product) {
      container.querySelector('#planned-quantity').textContent = plan.計画数量?.toLocaleString() || '0';
      container.querySelector('#actual-quantity').textContent = actualQuantity?.toLocaleString() || '0';

      const achievementRate = plan.計画数量 > 0 ? Math.round((actualQuantity / plan.計画数量) * 100) : 0;
      const rateEl = container.querySelector('#achievement-rate');
      rateEl.textContent = achievementRate + '%';
      rateEl.style.color = achievementRate >= 100 ? '#22c55e' : achievementRate >= 80 ? '#f59e0b' : '#ef4444';

      container.querySelector('#plan-period').textContent = 
        `${new Date(plan.生産開始予定日).toLocaleDateString('ja-JP')} ～ ${new Date(plan.生産完了予定日).toLocaleDateString('ja-JP')}`;

      container.querySelector('#plan-comparison').style.display = 'block';
      container.querySelector('#no-plan-message').style.display = 'none';
    } else {
      container.querySelector('#plan-comparison').style.display = 'none';
      container.querySelector('#no-plan-message').style.display = 'block';
    }
  }

  // 製品選択時の計画比較更新
  container.querySelector('select[name="productId"]').addEventListener('change', (e) => {
    const actualQuantity = parseInt(container.querySelector('input[name="totalQuantity"]').value) || 0;
    updatePlanComparison(e.target.value, actualQuantity);
  });

  // 生産数量入力時の計画比較更新
  container.querySelector('input[name="totalQuantity"]').addEventListener('input', (e) => {
    const productId = container.querySelector('select[name="productId"]').value;
    const actualQuantity = parseInt(e.target.value) || 0;
    updatePlanComparison(productId, actualQuantity);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-input').value.toLowerCase();
    const rows = await window.aivicApi.list(4);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword)
      );
      renderRows(filtered);
    }
  });

  // 実績登録
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const form = container.querySelector('#production-form');
    const formData = new FormData(form);

    const totalQuantity = parseInt(formData.get('totalQuantity')) || 0;
    const goodQuantity = parseInt(formData.get('goodQuantity')) || 0;
    const defectQuantity = parseInt(formData.get('defectQuantity')) || 0;

    const data = {
      生産ラインID: formData.get('productionLineId'),
      製品ID: formData.get('productId'),
      生産開始日時: formData.get('startTime'),
      生産終了日時: formData.get('endTime'),
      生産数量: totalQuantity,
      良品数量: goodQuantity,
      不良品数量: defectQuantity,
      作業時間: formData.get('startTime') && formData.get('endTime') ? 
        Math.round((new Date(formData.get('endTime')) - new Date(formData.get('startTime'))) / (1000 * 60)) : null,
      稼働率: totalQuantity > 0 ? Math.round((goodQuantity / totalQuantity) * 100) : 0,
      備考: formData.get('remarks'),
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(4, data);
    if (saved) {
      form.reset();
      updatePlanComparison('', 0);
      const rows = await window.aivicApi.list(4);
      if (rows) renderRows(rows);
    }
  });

  // 更新処理
  container.querySelector('#btn-update').addEventListener('click', async () => {
    if (!editingId) return;

    const form = container.querySelector('#production-form');
    const formData = new FormData(form);

    const totalQuantity = parseInt(formData.get('totalQuantity')) || 0;
    const goodQuantity = parseInt(formData.get('goodQuantity')) || 0;
    const defectQuantity = parseInt(formData.get('defectQuantity')) || 0;

    const data = {
      生産ラインID: formData.get('productionLineId'),
      製品ID: formData.get('productId'),
      生産開始日時: formData.get('startTime'),
      生産終了日時: formData.get('endTime'),
      生産数量: totalQuantity,
      良品数量: goodQuantity,
      不良品数量: defectQuantity,
      作業時間: formData.get('startTime') && formData.get('endTime') ? 
        Math.round((new Date(formData.get('endTime')) - new Date(formData.get('startTime'))) / (1000 * 60)) : null,
      稼働率: totalQuantity > 0 ? Math.round((goodQuantity / totalQuantity) * 100) : 0,
      備考: formData.get('remarks')
    };

    const updated = await window.aivicApi.update(4, editingId, data);
    if (updated) {
      form.reset();
      editingId = null;
      updatePlanComparison('', 0);
      container.querySelector('#btn-save').style.display = 'inline-block';
      container.querySelector('#btn-update').style.display = 'none';
      container.querySelector('#btn-cancel').style.display = 'none';
      const rows = await window.aivicApi.list(4);
      if (rows) renderRows(rows);
    }
  });

  // キャンセル処理
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    const form = container.querySelector('#production-form');
    form.reset();
    editingId = null;
    updatePlanComparison('', 0);
    container.querySelector('#btn-save').style.display = 'inline-block';
    container.querySelector('#btn-update').style.display = 'none';
    container.querySelector('#btn-cancel').style.display = 'none';
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    const headers = ['生産日時', 'ライン', '製品', '生産数量', '良品数量', '不良品数量', '作業者', '稼働率', '備考'];
    const csvData = [
      headers.join(','),
      ...rows.map(r => [
        new Date(r.生産開始日時).toLocaleString('ja-JP'),
        r.生産ライン名 || '',
        r.製品名 || '',
        r.生産数量 || 0,
        r.良品数量 || 0,
        r.不良品数量 || 0,
        r.作業者名 || '',
        (r.稼働率 || 0) + '%',
        (r.備考 || '').replace(/,/g, '，')
      ].map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `生産実績_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(4);
      const record = rows?.find(r => r.id === id);

      if (record) {
        editingId = id;
        const form = container.querySelector('#production-form');

        // フォームに値を設定
        form.querySelector('select[name="productionLineId"]').value = record.生産ラインID || '';
        form.querySelector('select[name="productId"]').value = record.製品ID || '';
        form.querySelector('input[name="startTime"]').value = record.生産開始日時 ? 
          new Date(record.生産開始日時).toISOString().slice(0, 16) : '';
        form.querySelector('input[name="endTime"]').value = record.生産終了日時 ? 
          new Date(record.生産終了日時).toISOString().slice(0, 16) : '';
        form.querySelector('input[name="totalQuantity"]').value = record.生産数量 || '';
        form.querySelector('input[name="goodQuantity"]').value = record.良品数量 || '';
        form.querySelector('input[name="defectQuantity"]').value = record.不良品数量 || '';
        form.querySelector('input[name="workerName"]').value = record.作業者名 || '';
        form.querySelector('textarea[name="remarks"]').value = record.備考 || '';

        // ボタン表示切り替え
        container.querySelector('#btn-save').style.display = 'none';
        container.querySelector('#btn-update').style.display = 'inline-block';
        container.querySelector('#btn-cancel').style.display = 'inline-block';

        // 計画比較更新
        updatePlanComparison(record.製品ID, record.生産数量);
      }
    }

    if (deleteBtn) {
      if (!confirm('この実績データを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(4, id);
      const rows = await window.aivicApi.list(4);
      if (rows) renderRows(rows);
    }
  });
}

function(container, apiUrl, tables) {
  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    const tbody = container.querySelector("#results-tbody");
    tbody.innerHTML = rows.map(r => {
      const productionDate = r.生産開始日時 ? new Date(r.生産開始日時).toLocaleDateString('ja-JP') : '';
      const qualityRate = r.生産数量 > 0 ? Math.round((r.良品数量 / r.生産数量) * 100) : 0;

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text);">${productionDate}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text);">${r.生産ライン名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text);">${r.製品名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); text-align: right;">${r.生産数量 || 0}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); text-align: right;">${r.良品数量 || 0}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); text-align: right;">${r.不良品数量 || 0}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); text-align: right;">${r.稼働率 || 0}%</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); text-align: right;">${qualityRate}%</td>
      </tr>`;
    }).join("");
  }

  // 2. KPI更新関数
  function updateKPIs(rows) {
    const totalProduction = rows.reduce((sum, r) => sum + (r.生産数量 || 0), 0);
    const avgEfficiency = rows.length > 0 ? Math.round(rows.reduce((sum, r) => sum + (r.稼働率 || 0), 0) / rows.length) : 0;
    const totalGood = rows.reduce((sum, r) => sum + (r.良品数量 || 0), 0);
    const qualityRate = totalProduction > 0 ? Math.round((totalGood / totalProduction) * 100) : 0;
    const defectRate = 100 - qualityRate;

    container.querySelector("#kpi-total-production").textContent = totalProduction.toLocaleString();
    container.querySelector("#kpi-avg-efficiency").textContent = avgEfficiency;
    container.querySelector("#kpi-quality-rate").textContent = qualityRate;
    container.querySelector("#kpi-defect-rate").textContent = defectRate;
  }

  // 3. チャート描画関数
  function drawProductionChart(rows) {
    const canvas = container.querySelector("#production-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 日別集計
    const dailyData = {};
    rows.forEach(r => {
      if (r.生産開始日時) {
        const date = new Date(r.生産開始日時).toLocaleDateString('ja-JP');
        dailyData[date] = (dailyData[date] || 0) + (r.生産数量 || 0);
      }
    });

    const dates = Object.keys(dailyData).sort();
    const values = dates.map(d => dailyData[d]);
    const maxValue = Math.max(...values, 1);

    // グラフ描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    dates.forEach((date, i) => {
      const x = 50 + (i * (canvas.width - 100)) / Math.max(dates.length - 1, 1);
      const y = canvas.height - 50 - (values[i] * (canvas.height - 100)) / maxValue;

      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);

      // データポイント
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    ctx.stroke();

    // 軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('生産量推移', 10, 20);
  }

  function drawEfficiencyMeter(efficiency) {
    const canvas = container.querySelector("#efficiency-meter");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 70;

    // 背景円
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 10;
    ctx.stroke();

    // 進捗円
    const angle = (efficiency / 100) * 2 * Math.PI - Math.PI / 2;
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, -Math.PI / 2, angle);
    ctx.strokeStyle = efficiency >= 80 ? '#4ade80' : efficiency >= 60 ? '#f59e0b' : '#ef4444';
    ctx.lineWidth = 10;
    ctx.stroke();

    // 中央テキスト
    ctx.fillStyle = '#d0e4ff';
    ctx.font = 'bold 24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`${efficiency}%`, centerX, centerY + 8);
  }

  function drawQualityChart(rows) {
    const canvas = container.querySelector("#quality-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const totalGood = rows.reduce((sum, r) => sum + (r.良品数量 || 0), 0);
    const totalDefect = rows.reduce((sum, r) => sum + (r.不良品数量 || 0), 0);
    const total = totalGood + totalDefect;

    if (total === 0) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 60;

    // 良品（緑）
    const goodAngle = (totalGood / total) * 2 * Math.PI;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.arc(centerX, centerY, radius, 0, goodAngle);
    ctx.fillStyle = '#4ade80';
    ctx.fill();

    // 不良品（赤）
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.arc(centerX, centerY, radius, goodAngle, 2 * Math.PI);
    ctx.fillStyle = '#ef4444';
    ctx.fill();

    // ラベル
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(`良品: ${Math.round((totalGood/total)*100)}%`, 10, canvas.height - 30);
    ctx.fillText(`不良: ${Math.round((totalDefect/total)*100)}%`, 10, canvas.height - 15);
  }

  function drawPlanActualChart(rows) {
    const canvas = container.querySelector("#plan-actual-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ（実際は生産計画テーブルと照合）
    const planData = [1000, 1200, 800, 1500, 900];
    const actualData = rows.slice(0, 5).map(r => r.生産数量 || 0);

    const maxValue = Math.max(...planData, ...actualData, 1);
    const barWidth = 30;
    const spacing = 50;

    planData.forEach((plan, i) => {
      const x = 50 + i * spacing;
      const actual = actualData[i] || 0;

      // 計画（青）
      const planHeight = (plan / maxValue) * (canvas.height - 80);
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, canvas.height - 40 - planHeight, barWidth, planHeight);

      // 実績（緑）
      const actualHeight = (actual / maxValue) * (canvas.height - 80);
      ctx.fillStyle = '#4ade80';
      ctx.fillRect(x + barWidth + 5, canvas.height - 40 - actualHeight, barWidth, actualHeight);
    });

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '10px sans-serif';
    ctx.fillText('計画', 10, 20);
    ctx.fillText('実績', 50, 20);
  }

  // 4. 初期データ読み込みと描画
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      renderRows(rows);
      updateKPIs(rows);
      drawProductionChart(rows);
      drawEfficiencyMeter(rows.length > 0 ? Math.round(rows.reduce((sum, r) => sum + (r.稼働率 || 0), 0) / rows.length) : 0);
      drawQualityChart(rows);
      drawPlanActualChart(rows);
    }
  });

  // 5. 集計実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const startDate = container.querySelector("#date-start").value;
    const endDate = container.querySelector("#date-end").value;
    const lineFilter = container.querySelector("#line-filter").value;
    const categoryFilter = container.querySelector("#category-filter").value;

    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    let filteredRows = rows;

    // フィルタリング
    if (startDate) {
      filteredRows = filteredRows.filter(r => r.生産開始日時 && new Date(r.生産開始日時) >= new Date(startDate));
    }
    if (endDate) {
      filteredRows = filteredRows.filter(r => r.生産開始日時 && new Date(r.生産開始日時) <= new Date(endDate));
    }
    if (lineFilter) {
      filteredRows = filteredRows.filter(r => r.生産ライン名 && r.生産ライン名.includes(lineFilter));
    }

    renderRows(filteredRows);
    updateKPIs(filteredRows);
    drawProductionChart(filteredRows);
    drawEfficiencyMeter(filteredRows.length > 0 ? Math.round(filteredRows.reduce((sum, r) => sum + (r.稼働率 || 0), 0) / filteredRows.length) : 0);
    drawQualityChart(filteredRows);
    drawPlanActualChart(filteredRows);
  });

  // 6. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    const headers = ["生産日", "ライン", "製品名", "生産数量", "良品数量", "不良品数量", "稼働率", "品質率"];
    const csvData = [headers.join(",")];

    rows.forEach(r => {
      const productionDate = r.生産開始日時 ? new Date(r.生産開始日時).toLocaleDateString('ja-JP') : '';
      const qualityRate = r.生産数量 > 0 ? Math.round((r.良品数量 / r.生産数量) * 100) : 0;

      const row = [
        productionDate,
        r.生産ライン名 || '',
        r.製品名 || '',
        r.生産数量 || 0,
        r.良品数量 || 0,
        r.不良品数量 || 0,
        (r.稼働率 || 0) + '%',
        qualityRate + '%'
      ];
      csvData.push(row.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "production_analysis_" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
  });

  // 7. 初期日付設定
  const today = new Date();
  const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  container.querySelector("#date-start").value = lastMonth.toISOString().slice(0, 10);
  container.querySelector("#date-end").value = today.toISOString().slice(0, 10);
}

function(container, apiUrl, tables) {
  // 1. 履歴テーブル再描画関数
  function renderHistory(reports) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = reports.map(r => `
      <tr data-id="${r.id}">
        <td>${r.レポート名 || ''}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; background: rgba(59, 130, 246, 0.15); color: #60a5fa;">
            ${r.レポート種別 || ''}
          </span>
        </td>
        <td>${r.対象期間開始 ? new Date(r.対象期間開始).toLocaleDateString() : ''} - ${r.対象期間終了 ? new Date(r.対象期間終了).toLocaleDateString() : ''}</td>
        <td>${r.ファイル形式 || ''}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; ${r.ステータス === '完了' ? 'background: rgba(34, 197, 94, 0.15); color: #4ade80;' : r.ステータス === 'エラー' ? 'background: rgba(239, 68, 68, 0.15); color: #f87171;' : 'background: rgba(251, 191, 36, 0.15); color: #fbbf24;'}">
            ${r.ステータス || ''}
          </span>
        </td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleString() : ''}</td>
        <td>
          <button class="action-btn secondary download-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 12px; margin-right: 4px;">
            ダウンロード
          </button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 12px;">
            削除
          </button>
        </td>
      </tr>
    `).join('');
  }

  // 2. 初期データ表示（生成レポートテーブル）
  const reportTableIndex = tables.findIndex(t => t.tableName === '生成レポート');
  if (reportTableIndex >= 0) {
    renderHistory(tables[reportTableIndex].records || []);
  }

  // 3. プレビュー生成関数
  function generatePreview() {
    const reportType = container.querySelector('#report-type').value;
    const startDate = container.querySelector('#start-date').value;
