function(container, apiUrl, tables) {
  // 統合結果プレビュー再描画関数
  function renderIntegrationPreview(data) {
    const tbody = container.querySelector('#integration-preview-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); padding: 20px;">統合データがありません</td></tr>';
