        <td>${item.生産数量 || 0}</td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(4), // 生産実績
    window.aivicApi.list(1)  // 生産ライン
  ]).then(([productionData, lineData]) => {
