          ${line.ライン名} - ${line.場所 || ''}
        </label>
      `).join('');
    }
  });

  // データ統合実行
  container.querySelector('#integration-execute-btn').addEventListener('click', async () => {
    const dataSource = container.querySelector('#data-source-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const selectedLines = Array.from(container.querySelectorAll('#production-lines input:checked')).map(cb => cb.value);
    const productCategory = container.querySelector('#product-category-select').value;

    if (!dataSource) {
      alert('データソースを選択してください');
      return;
    }

    // プログレスバー表示
    const progressDiv = container.querySelector('#integration-progress');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressDiv.style.display = 'block';

    // 進捗シミュレーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + '%';
      progressText.textContent = Math.round(progress) + '%';

      if (progress >= 100) {
        clearInterval(progressInterval);
        // 統合完了後にデータ取得
        loadIntegratedData();
      }
    }, 200);

    async function loadIntegratedData() {
      try {
        const productionData = await window.aivicApi.list(4); // 生産実績
        const productData = await window.aivicApi.list(2);    // 製品
        const lineData = await window.aivicApi.list(1);       // 生産ライン

        // データ統合処理（簡易版）
        const integratedData = productionData.map(prod => {
          const product = productData.find(p => p.製品ID === prod.製品ID);
          const line = lineData.find(l => l.生産ラインID === prod.生産ラインID);

          return {
            ...prod,
            製品名: product?.製品名 || '不明',
            ライン名: line?.ライン名 || '不明'
          };
        }).filter(item => {
          // フィルタリング
          if (selectedLines.length > 0 && !selectedLines.includes(item.生産ラインID)) return false;
          if (productCategory && item.カテゴリ !== productCategory) return false;
          if (startDate && new Date(item.生産開始日時) < new Date(startDate)) return false;
          if (endDate && new Date(item.生産開始日時) > new Date(endDate)) return false;
          return true;
        });

        renderIntegrationPreview(integratedData);
      } catch (error) {
        console.error('データ統合エラー:', error);
        alert('データ統合中にエラーが発生しました');
      }
    }
  });

  // 分析実行
  container.querySelector('#analysis-execute-btn').addEventListener('click', async () => {
    const analysisType = container.querySelector('input[name="analysis-type"]:checked')?.value;

    if (!analysisType) {
      alert('分析種別を選択してください');
      return;
    }

    try {
      const productionData = await window.aivicApi.list(4);

      // チャート描画
      const canvas = container.querySelector('#analysis-chart');
      const ctx = canvas.getContext('2d');
      const placeholder = container.querySelector('#chart-placeholder');

      placeholder.style.display = 'none';

      // キャンバスクリア
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // 簡易チャート描画
      drawAnalysisChart(ctx, productionData, analysisType);

    } catch (error) {
      console.error('分析実行エラー:', error);
      alert('分析実行中にエラーが発生しました');
    }
  });

  // チャート描画関数
  function drawAnalysisChart(ctx, data, analysisType) {
    const width = ctx.canvas.width;
    const height = ctx.canvas.height;
    const padding = 40;

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;

    // 縦線
    for (let i = 1; i < 5; i++) {
      const x = padding + (width - padding * 2) * i / 5;
      ctx.beginPath();
      ctx.moveTo(x, padding);
      ctx.lineTo(x, height - padding);
      ctx.stroke();
    }

    // 横線
    for (let i = 1; i < 4; i++) {
      const y = padding + (height - padding * 2) * i / 4;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();
    }

    // データポイント描画
    if (data && data.length > 0) {
      ctx.fillStyle = '#4a9eff';
      ctx.strokeStyle = '#4a9eff';
      ctx.lineWidth = 2;

      const points = data.slice(0, 10).map((item, index) => ({
        x: padding + (width - padding * 2) * index / 9,
        y: padding + (height - padding * 2) * (1 - (item.生産数量 || 0) / 1000)
      }));

      // 線グラフ
      ctx.beginPath();
      points.forEach((point, index) => {
        if (index === 0) {
          ctx.moveTo(point.x, point.y);
        } else {
          ctx.lineTo(point.x, point.y);
        }
      });
      ctx.stroke();

      // ポイント
      points.forEach(point => {
        ctx.beginPath();
        ctx.arc(point.x, point.y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    // タイトル
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(getAnalysisTitle(analysisType), width / 2, 25);
  }

  function getAnalysisTitle(type) {
    const titles = {
      trend: '生産トレンド分析',
      efficiency: '稼働効率分析', 
      quality: '品質分析',
      comparison: '計画対実績比較'
    };
    return titles[type] || '分析結果';
  }

  // レポート生成
  container.querySelector('#generate-report-btn').addEventListener('click', async () => {
    const format = container.querySelector('#report-format-select').value;

    if (!format) {
      alert('出力形式を選択してください');
      return;
    }

    try {
      const reportData = {
        レポート名: `データ統合分析レポート_${new Date().toISOString().split('T')[0]}`,
        レポート種別: 'データ統合分析',
        対象期間開始: container.querySelector('#start-date').value || new Date().toISOString(),
        対象期間終了: container.querySelector('#end-date').value || new Date().toISOString(),
        ファイル形式: format.toUpperCase(),
        ステータス: '生成完了',
        作成者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(6, reportData); // 生成レポートテーブル

      if (saved) {
        alert(`${format.toUpperCase()}レポートを生成しました`);
      } else {
        alert('レポート生成に失敗しました');
      }
    } catch (error) {
      console.error('レポート生成エラー:', error);
      alert('レポート生成中にエラーが発生しました');
    }
  });

  // 初期日付設定
  const today = new Date();
  const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());

  container.querySelector('#start-date').value = lastMonth.toISOString().split('T')[0];
  container.querySelector('#end-date').value = today.toISOString().split('T')[0];
}

