          ステータス: "完了",
          ファイルサイズ: Math.floor(Math.random() * 1000000) + 100000,
          作成者ID: "current-user",
          完了日時: new Date().toISOString()
        };

        await window.aivicApi.save(6, generatedReport); // 生成レポートテーブル

        // 履歴を再読み込み
        const reports = await window.aivicApi.list(6);
        if (reports) {
          renderHistory(reports);
        }

        alert("レポートが正常に生成されました");
      }
    } catch (error) {
      alert("レポート生成中にエラーが発生しました");
    } finally {
      modal.style.display = "none";
    }
  }

  // 初期データ読み込み
  window.aivicApi.list(6).then(reports => {
    if (reports) {
      renderHistory(reports);
    }
  });

  // イベントリスナー
  container.querySelector("#btn-preview").addEventListener("click", showPreview);
  container.querySelector("#btn-generate").addEventListener("click", generateReport);

  // ダウンロードボタンのイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const downloadBtn = e.target.closest(".download-btn");
    if (downloadBtn) {
      const reportId = downloadBtn.dataset.id;
      alert(`レポート ${reportId} のダウンロードを開始します`);
    }
  });

  // デフォルト値設定
  const today = new Date();
  const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);

  container.querySelector("#start-date").value = lastMonth.toISOString().split('T')[0];
  container.querySelector("#end-date").value = lastMonthEnd.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
