      title: "小売業のオムニチャネル戦略動向",
      category: "小売業", 
      region: "関西",
      publishDate: "2024-01-08",
      reliability: "高",
      content: "小売業界ではオンラインとオフラインを統合したオムニチャネル戦略が主流となり、関連システム投資が拡大している。",
      source: "小売業界研究所",
      marketSize: 670000000
    }
  ];

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" class="cursor-pointer hover:bg-opacity-50" style="hover:background: rgba(255,255,255,0.05);">
        <td class="font-medium">${r.title || ""}</td>
        <td>
          <span class="px-2 py-1 rounded text-xs" style="background: rgba(0,168,255,0.2); color: var(--text);">
            ${r.category || ""}
          </span>
        </td>
        <td>${r.region || ""}</td>
        <td>${r.publishDate || ""}</td>
        <td>
          <span class="px-2 py-1 rounded text-xs ${r.reliability === '高' ? 'bg-green-100 text-green-800' : r.reliability === '中' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}" 
                style="background: ${r.reliability === '高' ? 'rgba(46,213,115,0.2)' : r.reliability === '中' ? 'rgba(255,165,0,0.2)' : 'rgba(255,107,107,0.2)'}; color: var(--text);">
            ${r.reliability || ""}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join("");

    resultCount.textContent = `${rows.length}件`;
  }

  // トレンドチャート描画
  function drawTrendChart() {
    const ctx = trendChart.getContext('2d');
    const width = trendChart.width;
    const height = trendChart.height;

    ctx.clearRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // トレンドライン
    const data = [120, 135, 142, 158, 171, 189, 205, 218, 235, 248, 265, 280];
    ctx.strokeStyle = '#00a8ff';
    ctx.lineWidth = 3;
    ctx.beginPath();

    for (let i = 0; i < data.length; i++) {
      const x = 40 + (width - 60) * (i / (data.length - 1));
      const y = height - 20 - (height - 40) * (data[i] - 100) / 200;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('市場規模推移', 10, 20);
  }

  // 需要予測チャート描画
  function drawDemandChart() {
    const ctx = demandChart.getContext('2d');
    const width = demandChart.width;
    const height = demandChart.height;

    ctx.clearRect(0, 0, width, height);

    // 棒グラフ
    const data = [85, 92, 98, 105, 112];
    const labels = ['Q1', 'Q2', 'Q3', 'Q4', 'Q1予測'];
    const barWidth = (width - 60) / data.length;

    for (let i = 0; i < data.length; i++) {
      const x = 30 + i * barWidth + 5;
      const barHeight = (height - 60) * (data[i] / 120);
      const y = height - 30 - barHeight;

      ctx.fillStyle = i === data.length - 1 ? '#ff6a00' : '#2ed573';
      ctx.fillRect(x, y, barWidth - 10, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(labels[i], x + (barWidth - 10) / 2, height - 10);
      ctx.fillText(data[i], x + (barWidth - 10) / 2, y - 5);
    }
  }

  // 初期データ描画
  renderRows(marketData);
  drawTrendChart();
  drawDemandChart();

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const category = container.querySelector("#category-filter").value;
    const region = container.querySelector("#region-filter").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const keyword = container.querySelector("#keyword-search").value;

    let filtered = marketData.filter(item => {
      if (category && item.category !== category) return false;
      if (region && item.region !== region && item.region !== "全国") return false;
      if (startDate && item.publishDate < startDate) return false;
      if (endDate && item.publishDate > endDate) return false;
      if (keyword && !JSON.stringify(item).toLowerCase().includes(keyword.toLowerCase())) return false;
      return true;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    const headers = ["情報タイトル", "カテゴリ", "地域", "発表日", "信頼度", "情報源", "市場規模"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...marketData.map(row => [
        `"${row.title}"`,
        `"${row.category}"`, 
        `"${row.region}"`,
        row.publishDate,
        `"${row.reliability}"`,
        `"${row.source}"`,
        row.marketSize
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "market_info_export.csv";
    link.click();
  });

  // 詳細表示モーダル
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const item = marketData.find(m => m.id === id);
      if (item) {
        modalTitle.textContent = item.title;
        modalContent.innerHTML = `
          <div class="space-y-3">
            <div><strong>カテゴリ:</strong> ${item.category}</div>
            <div><strong>地域:</strong> ${item.region}</div>
            <div><strong>発表日:</strong> ${item.publishDate}</div>
            <div><strong>信頼度:</strong> ${item.reliability}</div>
            <div><strong>情報源:</strong> ${item.source}</div>
            <div><strong>市場規模:</strong> ${item.marketSize.toLocaleString()}円</div>
            <div><strong>内容:</strong><br>${item.content}</div>
          </div>
        `;
        detailModal.style.display = "flex";
      }
    }
  });

  // モーダル閉じる
  container.querySelector("#close-modal").addEventListener("click", () => {
    detailModal.style.display = "none";
  });

  // お気に入り登録
  container.querySelector("#add-favorite").addEventListener("click", () => {
    alert("お気に入りに登録しました");
    detailModal.style.display = "none";
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.style.display = "none";
    }
  });
}
